  // Unix source, patch whose only added line ends in \r with no newline after it
  let oldFile = 'line1\nline2\n';
  let newFile = 'line1\nline2\nline3\r';
  let patch = structuredPatch('f', 'f', oldFile, newFile, undefined, undefined, {context: 0});
